export const CYBER_INSURANCE_REQUIRED_SOURCES = Object.freeze({
  dependence: Object.freeze(['01', '04', '05', '06', '07']),
  window: Object.freeze(['06']),
  vertu: Object.freeze(['02', '03', '14', '15']),
  'marks-spencer': Object.freeze(['09', '10', '11']),
});

export function cyberInsuranceSvg(lang, kind) {
  if (typeof lang !== 'string' || !['fr', 'en'].includes(lang) || typeof kind !== 'string' || !CYBER_INSURANCE_KINDS.includes(kind)) throw new TypeError('Invalid cyber insurance figure variant');
  return FIGURES[`${kind}-${lang}`];
}

export function cyberInsuranceReferences(kind, sources) {
  if (typeof kind !== 'string' || !CYBER_INSURANCE_KINDS.includes(kind) || typeof sources !== 'string') throw new TypeError('Invalid cyber insurance source references');
  const references = sources.trim() ? sources.trim().split(/\s+/u) : [];
  const required = CYBER_INSURANCE_REQUIRED_SOURCES[kind];
  if (references.length !== required.length || new Set(references).size !== references.length || references.some(id => !required.includes(id))) throw new TypeError('Incomplete or invalid cyber insurance source references');
  return Object.freeze(references);
}

export function cyberInsuranceInlineSvg(lang, kind) {
  // Raw HTML is limited to the controlled static SVGs above.
  return cyberInsuranceSvg(lang, kind).replace(/^<svg /u, '<svg style="width:100%;height:auto" ');
}
